        'Device.IP.Interface.1.IPv4Address.1.IPAddress'
    ];

    result = getParameterValue(keys);
}

return {writable: false, value: [result, "xsd:string"]};

function getParameterValue(keys) {
    for (let key of keys) {
        if (key.includes('ExternalIPAddress')) {
            let connectionTypeKey = key.replace('ExternalIPAddress', 'ConnectionType');
            let connectionType = declare(connectionTypeKey, {value: Date.now()});
            if (connectionType.size && connectionType.value[0] === 'bridge') {
                continue;
            }
        }

        let d = declare(key, {path: Date.now() - (120 * 1000), value: Date.now()});

        for (let item of d) {
            if (item.value && item.value[0] && item.value[0] !== '0.0.0.0') {
                return item.value[0];
            }
        }
    }

    return '';
}

// VirtualParameter: pppoeMac (Multi-vendor TR-098 & TR-181)
let result = "";

function isValidMac(s) {
  if (!s || typeof s !== 'string') return false;
  s = s.trim();
  if (s === '00:00:00:00:00:00' || s === 'ff:ff:ff:ff:ff:ff' || s === '00-00-00-00-00-00') return false;
  return /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/.test(s);
}

// 1. WANPPPConnection MACs across all WANDevices and WANConnectionDevices
let w1 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.MACAddress", {value: Date.now()});
for (let p of w1) {
  if (p.value && isValidMac(p.value[0])) {
    result = p.value[0];
    break;
  }
}

// 2. WANIPConnection MACs
if (!result) {
  let w2 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.MACAddress", {value: Date.now()});
  for (let p of w2) {
    if (p.value && isValidMac(p.value[0])) {
      result = p.value[0];
      break;
    }
  }
}

// 3. F477V2 EPON specific Serial/MAC
if (!result) {
  let w3 = declare("InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber", {value: Date.now()});
  if (w3.size && isValidMac(w3.value[0])) {
    result = w3.value[0];
  }
}

// 4. DeviceInfo MACAddress
if (!result) {
  let w4 = declare("InternetGatewayDevice.DeviceInfo.MACAddress", {value: Date.now()});
  if (w4.size && isValidMac(w4.value[0])) {
    result = w4.value[0];
  }
}

// 5. LANDevice LANHostConfigManagement MAC
if (!result) {
  let w5 = declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MACAddress", {value: Date.now()});
  if (w5.size && isValidMac(w5.value[0])) {
    result = w5.value[0];
  }
}

// 6. WLAN BSSID fallback
