  let w6 = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.BSSID", {value: Date.now()});
  if (w6.size && isValidMac(w6.value[0])) {
    result = w6.value[0];
  }
}

// 7. TR-181 standard Ethernet Interface MAC
